const slots=figma.currentPage.findAll(n=>n.type==='INSTANCE'&&mediaIds.has(n.mainComponent?.id));
const inputs=figma.currentPage.findAll(n=>n.type==='INSTANCE'&&familyIds.has(n.mainComponent?.id));
const failures=[],summary=[];
const intersects=(a,b)=>a.x < b.x+b.width-0.1&&a.x+a.width>b.x+0.1&&a.y<b.y+b.height-0.1&&a.y+a.height>b.y+0.1;
