 const pieces=n.children.filter(c=>c.visible);
 for(let i=0;i<pieces.length;i++){
  const a=pieces[i];
  if(a.x<-.1||a.y<-.1||a.x+a.width>n.width+.1||a.y+a.height>n.height+.1)failures.push({id:n.id,issue:'content outside attachment',child:a.id});
  for(let j=i+1;j<pieces.length;j++)if(intersects(a,pieces[j]))failures.push({id:n.id,issue:'attachment regions overlap',children:[a.id,pieces[j].id]});
 }
 const remove=pieces.find(c=>c.type==='INSTANCE'&&c.name.startsWith('Remove'));
 if(remove&&(remove.width<32||remove.height<32))failures.push({id:n.id,issue:'remove target below 32px'});
 const preview=pieces.find(c=>c.name==='Input preview');
 if(preview){const glyphs=preview.children.filter(c=>c.type==='INSTANCE'&&c.visible);if(glyphs.length!==1)failures.push({id:n.id,issue:'preview contains control collision'});for(const g of glyphs)if(Math.abs(g.x+g.width/2-preview.width/2)>.1||Math.abs(g.y+g.height/2-preview.height/2)>.1)failures.push({id:n.id,issue:'status glyph not centered'});}
 const label=pieces.find(c=>c.type==='TEXT');
 if(label&&n.componentProperties['Label#1028:37']?.value!==label.characters)failures.push({id:n.id,issue:'rendered identity differs from property',expected:n.componentProperties['Label#1028:37']?.value,actual:label.characters});
 if(!label||label.width<60||label.height>48||!label.characters.trim())failures.push({id:n.id,issue:'unreadable identity'});
 summary.push({id:n.id,main:n.mainComponent.id,text:label?.characters,wh:[n.width,n.height]});
}
const consumers=slots.map(n=>{let a=n;const path=[];while(a&&a.type!=='PAGE'){path.push({id:a.id,name:a.name});a=a.parent;}return {id:n.id,main:n.mainComponent.id,path};});
return {page:{id:figma.currentPage.id,name:figma.currentPage.name},mediaSlotCount:slots.length,inputCount:inputs.length,passed:failures.length===0,failures,consumers:consumers.map(c=>({id:c.id,main:c.main,composer:c.path[1],screen:c.path.find(p=>/^(G\\d\\d|State=G)/.test(p.name))}))};
